package org.apache.commons.jxpath.ri.compiler;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.jxpath.Expression;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.InfoSetUtil;
import org.apache.commons.jxpath.ri.axes.InitialContext;
import org.apache.commons.jxpath.ri.axes.SelfContext;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.when;

public class CoreOperationCompare_findMatch_TriageGen2Test {

    private CoreOperationCompare sut;
    private Expression mockExpr1;
    private Expression mockExpr2;

    @Before
    public void setUp() {
        mockExpr1 = org.mockito.Mockito.mock(Expression.class);
        mockExpr2 = org.mockito.Mockito.mock(Expression.class);
        // We spy on the class to test the protected method and mock the internal 'contains' call
        sut = spy(new CoreOperationCompare(mockExpr1, mockExpr2));
    }

    /**
     * Test case where both iterators are empty.
     * Expected: returns false (no match possible).
     */
    @Test
    public void testFindMatch_BothEmpty() {
        Iterator<Object> lit = Collections.emptyIterator();
        Iterator<Object> rit = Collections.emptyIterator();

        boolean result = sut.findMatch(lit, rit);

        assertFalse(result);
    }

    /**
     * Test case where the left iterator is empty but the right is not.
     * Expected: returns false.
     */
    @Test
    public void testFindMatch_LeftEmptyRightNotEmpty() {
        Iterator<Object> lit = Collections.emptyIterator();
        Iterator<Object> rit = Arrays.asList("A", "B").iterator();

        // Even if rit has elements, left is empty, so contains will return false
        doAnswer(invocation -> false).when(sut).contains(any(), any());

        boolean result = sut.findMatch(lit, rit);

        assertFalse(result);
    }

    /**
     * Test case where a match is found.
     * Expected: returns true.
     */
    @Test
    public void testFindMatch_MatchFound() {
        Iterator<Object> lit = Arrays.asList("A", "B", "C").iterator();
        Iterator<Object> rit = Arrays.asList("B").iterator();

        // Mock contains to return true when it finds "B"
        doAnswer(invocation -> {
            Object val = invocation.getArgument(1);
            return "B".equals(val);
        }).when(sut).contains(any(), any());

        boolean result = sut.findMatch(lit, rit);

        assertTrue(result);
    }

    /**
     * Test case where no match is found despite elements in both.
     * Expected: returns false.
     */
    @Test
    public void testFindMatch_NoMatchFound() {
        Iterator<Object> lit = Arrays.asList("A", "B").iterator();
        Iterator<Object> rit = Arrays.asList("C", "D").iterator();

        // Mock contains to always return false
        doAnswer(invocation -> false).when(sut).contains(any(), any());

        boolean result = sut.findMatch(lit, rit);

        assertFalse(result);
    }

    /**
     * Test case where left iterator has elements but right iterator is empty.
     * Expected: returns false.
     */
    @Test
    public void testFindMatch_LeftNotEmptyRightEmpty() {
        Iterator<Object> lit = Arrays.asList("A", "B").iterator();
        Iterator<Object> rit = Collections.emptyIterator();

        boolean result = sut.findMatch(lit, rit);

        assertFalse(result);
    }
}
